 dict(t='Проверяем умножением', v=2, say='Разложили верно? Проверим обратным ходом: раскроем скобки 6·(x + 2) = 6x + 12. Получили исходное выражение — значит, всё правильно! Такая проверка обратным умножением — лучший друг при разложении.', prop='6(x+2) = 6x + 12 ✔'),
 dict(t='Разность квадратов — волшебная формула', v=3, say='Великая формула: a² − b² = (a − b)(a + b). Например, x² − 16 — это x² − 4², значит x² − 16 = (x − 4)(x + 4). Почему так? При перемножении скобок средние члены 4x и −4x взаимно уничтожаются, и остаётся только x² − 16.', prop='x² − 16 = (x−4)(x+4)'),
 dict(t='Откуда взялась формула', v=4, say='Проверим формулу руками: (a + b)² = (a + b)(a + b). Перемножаем каждый с каждым: a·a = a², a·b = ab, b·a = ab, b·b = b². Складываем: a² + 2ab + b². Запомни: в середине всегда 2ab, потому что ab встречается дважды!', prop='(a+b)² = a² + 2ab + b²'),
