 dict(t='Два главных приёма в одном месте', v=6, say='Итак, у нас два ключа: 1) вынести общий множитель: 6x + 12 = 6(x + 2); 2) применить формулу разности квадратов: x² − 16 = (x − 4)(x + 4). Оба приёма — это запись выражения в виде произведения, которое потом удобно сокращать и решать.', prop='6(x+2) · (x−4)(x+4)'),
 dict(t='Проверь себя', v=7, say='Разложи на множители: x² − 16. Вспомни формулу a² − b² = (a − b)(a + b): чему равны a и b в нашем примере?', prop='x² − 16 = ?'),
