 dict(t='Складываем уравнения', v=2, say='Складываем левые части: x + x = 2x, y + (−y) = 0. Складываем правые части: 10 + 4 = 14. Получаем простое уравнение 2x = 14, из которого сразу находим x = 7. Отлично, половина ответа готова!', prop='2x = 14 → x = 7'),
 dict(t='Находим y', v=3, say='Теперь подставим найденное x = 7 в любое уравнение, например в первое: 7 + y = 10. Отсюда y = 10 − 7 = 3. Решение системы — пара чисел: x = 7, y = 3, коротко записывают (7; 3).', prop='7 + y = 10 → y = 3'),
 dict(t='Проверяем ответ', v=4, say='Обязательная проверка: подставим пару (7; 3) в оба уравнения. Первое: 7 + 3 = 10 ✔. Второе: 7 − 3 = 4 ✔. Всё сошлось — значит, система решена верно! Никогда не пропускай проверку.', prop='(7; 3): 10 ✔ и 4 ✔'),
 dict(t='Второй способ — подстановка', v=5, say='Иногда удобнее метод подстановки: из первого уравнения выражаем y = 10 − x и подставляем во второе: x − (10 − x) = 4 → 2x − 10 = 4 → x = 7, а потом y = 3. Оба метода дают один и тот же ответ — выбирай, какой понятнее!', prop='y = 10 − x → подставляем'),
 dict(t='Где встречаются системы', v=6, say='Системы решают задачи «на два условия»: возраст двух братьев, если один старше на 4 года, а вместе им 10 лет — это как раз наша система! Длина и ширина прямоугольника, цена ручки и тетради — везде прячутся системы.', prop='два условия → система'),
 dict(t='Проверь себя', v=7, say='Реши систему {x + y = 10; x − y = 4}. Мы уже нашли x = 7. Чему равен y? Проверь себя и переходи к заданиям!', prop='x = 7 → y = ?'),
